"""CPU-only dependency proof for V178 GPU work; absence alone is not success."""

import hashlib
import json
from pathlib import Path

import psutil


def read(path):
    return json.loads(Path(path).read_text())


def ref(path):
    path = Path(path).absolute()
    with path.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    return {"path": str(path), "sha256": digest}


def owner_live(owner):
    """Transient/permission errors propagate, never turning an owner terminal."""
    try:
        process = psutil.Process(owner["pid"])
        return process.create_time() == owner["created"] and process.status() not in (
            psutil.STATUS_ZOMBIE,
            psutil.STATUS_DEAD,
        )
    except psutil.NoSuchProcess:
        return False


def dependency_readiness(root, *, is_live=owner_live):
    """Require terminal train/review/watch owners and the completed pipeline."""
    root = Path(root)
    for name in [
        "train-failure-v1.json",
        "review-failure-v1.json",
        "completion-watch-failure-v1.json",
    ]:
        if (root / name).exists():
            raise RuntimeError(f"Preserved dependency failure requires inspection: {root / name}")
    bindings, owners = [], {}
    phases = [
        ("train", "train-result-v1.json"),
        ("review", "scores-v1.json"),
        ("completion-watch", "completion-watch-result-v1.json"),
    ]
    for phase, result_name in phases:
        launch_path = root / f"{phase}-launch-v1.json"
        if not launch_path.exists():
            return {"ready": False, "reason": f"waiting-for-{phase}-launch"}
        launch = read(launch_path)
        owner = launch["owner"]
        owners[phase] = owner
        if is_live(owner):
            return {"ready": False, "reason": f"waiting-for-{phase}-owner", "owner": owner}
        result_path = root / result_name
        if not result_path.exists():
            return {
                "ready": False,
                "reason": f"waiting-for-{phase}-completed-result",
                "owner": owner,
            }
        result = read(result_path)
        if result.get("owner") != owner or not result.get("status", "").startswith("completed"):
            raise RuntimeError(f"Dependency result does not prove {phase} success: {result_path}")
        bindings.extend([ref(launch_path), ref(result_path)])
    status_path = root / "completion-watch-status-v1.json"
    status = read(status_path)
    if (
        status["owner"] != owners["completion-watch"]
        or status["status"] != "ready-for-actual-native-viewing"
    ):
        raise RuntimeError("Completion watcher did not reach its final native-viewing state")
    for name in [
        "training-audit-v1.json",
        "quality-audit-v1.json",
        "offset-audit-v1.json",
        "paired-comparisons-v1.json",
        "figures-v1.json",
    ]:
        path = root / name
        if not path.exists():
            raise RuntimeError(f"Completed dependency is missing required output: {path}")
        value = read(path)
        if not value.get("status", "").startswith(("pass", "completed", "rendered")):
            raise RuntimeError(f"Dependency output lacks completed status: {path}")
        bindings.append(ref(path))
    bindings.append(ref(status_path))
    return {
        "ready": True,
        "reason": "all-V175-owners-terminal-completed-audits-review-render",
        "owners": owners,
        "bindings": bindings,
        "scope": "Ready for separate GPU admission;V175 human viewing/report/publication may remain.",
    }

"""Connect the pinned sampler's native first-order backward to Torch autograd.

V170 used the operator for inference. Training also needs this registration;
the pinned CPU/CUDA backward kernels are reused without numerical changes.
"""

import torch
from torch.autograd.function import once_differentiable

_registered = False


def enable_sampler_autograd():
    global _registered
    if _registered:
        return
    namespace = torch.ops.deform_neighbourhood_sampling
    if not hasattr(namespace, "deform_neighbourhood_backward"):
        raise RuntimeError("Load the pinned native sampling library before training")

    def setup_context(ctx, inputs, output):
        ctx.save_for_backward(*inputs[:2])
        ctx.options = inputs[2:]

    @once_differentiable
    def backward(ctx, gradient):
        first, offset = ctx.saved_tensors
        gradients = namespace.deform_neighbourhood_backward.default(
            gradient.contiguous(), first, offset, *ctx.options
        )
        return (*gradients, *(None for _ in ctx.options))

    torch.library.register_autograd(
        "deform_neighbourhood_sampling::deform_neighbourhood",
        backward,
        setup_context=setup_context,
    )
    _registered = True

"""Exact reviewed paired-case admission; quarantine is never admitted implicitly."""

import hashlib
import json
from pathlib import Path

from .paired import DEVELOPMENT_SCENES, TRAINING_SCENES

SOURCE_FAMILY = "rawnind-reviewed-paired-extension"
# Populate only after actual identity/content/registration review. A locally
# self-signed receipt or a changed quarantine split cannot add an entry here.
REVIEWED_ADMISSIONS = frozenset(
    {
        # 51 new publisher scene IDs, reviewed in docs/paired-extension-quarantine.md.
        "5609f2bcf17fa165828120dd25452a236a7631b89bab632fb18037161203b70e",
    }
)


def case_key(case):
    return case["scene"], case.get("noisy", {}).get("sha256")


def payload_digest(payload):
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
    ).hexdigest()


def _sha256(value):
    return (
        isinstance(value, str) and len(value) == 64 and all(c in "0123456789abcdef" for c in value)
    )


def approved_extension_cases(data):
    admission = data.get("paired_extension_admission")
    if admission is None:
        return {}
    payload = admission["payload"]
    digest = payload_digest(payload)
    if digest != admission.get("sha256") or digest not in REVIEWED_ADMISSIONS:
        raise ValueError("Paired extension admission is not an exact pinned review")
    if (
        payload.get("format_version") != 1
        or payload.get("source_family") != SOURCE_FAMILY
        or payload.get("scope") != "reviewed-training-only"
    ):
        raise ValueError("Unsupported paired extension admission")
    evidence = payload["evidence"]
    for name in ["acquisition_manifest", "screen_summary", "prepared_manifest", "manual_review"]:
        if not _sha256(evidence.get(name + "_sha256")):
            raise ValueError("Paired review evidence requires exact source hashes")
    protected = payload.get("protected_scene_names")
    if (
        not protected
        or not all(isinstance(name, str) and name for name in protected)
        or not set(DEVELOPMENT_SCENES) <= set(protected)
    ):
        raise ValueError("Paired admission must preserve protected scene identities")
    approved = {}
    for case in payload["cases"]:
        key = case_key(case)
        camera = "".join(
            c for c in case.get("metadata", {}).get("camera", "") if c.isalnum()
        ).upper()
        if (
            case.get("paired_source_family") != SOURCE_FAMILY
            or case["scene"] in protected
            or case["scene"] in TRAINING_SCENES
            or case["scene"].startswith(("MuseeL-", "LucieB_", "7D-", "D60-", "boardgames_"))
            or case.get("unknown_sensor")
            or case.get("source_permission", {}).get("license") not in {"CC0-1.0", "CC-BY-SA-4.0"}
            or not camera
            or camera == "UNKNOWN"
            or "EOSM100" in camera
            or camera.endswith("GH1")
            or not _sha256(key[1])
            or not case.get("references")
            or any(not _sha256(r.get("sha256")) for r in case["references"])
            or not case.get("crops")
            or key in approved
        ):
            raise ValueError("Invalid/protected/duplicate reviewed paired case")
        group = case.get("scene_group", case["scene"])
        if not isinstance(group, str) or not group or group in protected:
            raise ValueError("Invalid/protected reviewed paired scene group")
        for crop in case["crops"]:
            if not Path(crop["path"]).is_absolute() or not _sha256(crop.get("sha256")):
                raise ValueError("Reviewed paired crops require absolute paths and exact hashes")
        approved[key] = case
    if not approved:
        raise ValueError("Reviewed paired admission has no cases")
    return approved


def extend_paired_training(base_manifest, admission_path, output):
    """Build a separate reviewed extension while preserving all legacy cases."""
    from .paired_training import PairedDataset
    from .safety import writable_path

    base_manifest, admission_path = Path(base_manifest).resolve(), Path(admission_path).resolve()
    base_bytes, admission_bytes = base_manifest.read_bytes(), admission_path.read_bytes()
    base, payload = json.loads(base_bytes), json.loads(admission_bytes)
    if base.get("paired_extension_admission") is not None or base.get("split") != "train":
        raise ValueError("Choose the original train32 manifest, not an extension/quarantine")
    if {case["scene"] for case in base["cases"]} != set(TRAINING_SCENES):
        raise ValueError("Expected the complete fixed train32 selection")
    if base["dataset_license"].get("rightsIdentifier") != "CC-BY-SA-4.0":
        raise ValueError("Expected the reviewed RawNIND dataset license")
    PairedDataset(base_manifest, patch_size=32)
    envelope = {"payload": payload, "sha256": payload_digest(payload)}
    approved = approved_extension_cases({"paired_extension_admission": envelope})

    def source_hashes(cases):
        return {case["noisy"]["sha256"] for case in cases} | {
            ref["sha256"] for case in cases for ref in case["references"]
        }

    if source_hashes(base["cases"]) & source_hashes(approved.values()):
        raise ValueError("Reviewed paired source overlaps an existing train32 capture")
    cases = []
    for case in base["cases"]:
        cases.append(
            {
                **case,
                "crops": [
                    {**crop, "path": str((base_manifest.parent / crop["path"]).resolve())}
                    for crop in case["crops"]
                ],
            }
        )
    normalized_base = json.loads(json.dumps(cases))
    cases.extend(approved.values())
    result = {
        "format_version": 2,
        "split": "train",
        "cases": cases,
        "dataset_license": base["dataset_license"],
        "attribution": base["attribution"],
        "paired_extension_admission": envelope,
        "recipe": {
            "kind": "reviewed-paired-extension-v1",
            "base_manifest": str(base_manifest),
            "base_manifest_sha256": hashlib.sha256(base_bytes).hexdigest(),
            "admission_path": str(admission_path),
            "admission_file_sha256": hashlib.sha256(admission_bytes).hexdigest(),
            "admission_canonical_sha256": envelope["sha256"],
            "groups": "Original train32 scenes plus exact reviewed group aliases; repeated views/exposures share group weight",
        },
        "notes": [
            "Separate opt-in dataset; base/quarantine/source/crop bytes are unchanged.",
            "Measured clean CFA retains noise; independently calibrated AHD RGB is auxiliary, not exact GT.",
        ],
    }
    output = writable_path(output)
    output.mkdir(parents=True, exist_ok=False)
    path = output / "manifest.json"
    path.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    dataset = PairedDataset(path, patch_size=32)
    assert json.loads(path.read_text())["cases"][: len(normalized_base)] == normalized_base
    assert (
        base_manifest.read_bytes() == base_bytes and admission_path.read_bytes() == admission_bytes
    )
    archive = output / "source"
    archive.mkdir()
    (archive / "base-manifest.json").write_bytes(base_bytes)
    (archive / "admission.json").write_bytes(admission_bytes)
    sources = {}
    for source in Path(__file__).parent.glob("*.py"):
        content = source.read_bytes()
        (archive / source.name).write_bytes(content)
        sources[source.name] = hashlib.sha256(content).hexdigest()
    receipt = {
        "manifest": str(path),
        "manifest_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        "base_cases_preserved": len(normalized_base),
        "reviewed_new_cases": len(approved),
        "publisher_scene_ids": len({case["scene"] for case in cases}),
        "sampling_groups": len(dataset),
        "crops": sum(len(case["crops"]) for case in cases),
        "admission_canonical_sha256": envelope["sha256"],
        "source_files": sources,
        "base_and_admission_bytes_unchanged": True,
    }
    (output / "receipt.json").write_text(json.dumps(receipt, indent=2) + "\n")
    return receipt

"""Independent simulated-noise views and a convex conditional-mean objective."""

import hashlib
import math

import torch

from .cfa import mosaic
from .losses import reconstruction_loss
from .noise import add_noise, variance_map
from .precision import ieee_fp32

POLICY = "independent-sensor-noise-v1"


def noise_pair_options(config):
    draws = config.get("noise_pair_draws", 1)
    weight = config.get("conditional_mean_weight", 0.0)
    if type(draws) is not int or draws not in (1, 2):
        raise ValueError("noise_pair_draws must be one or two")
    if (
        isinstance(weight, bool)
        or not isinstance(weight, (int, float))
        or not math.isfinite(weight)
        or not 0 <= weight <= 1
    ):
        raise ValueError("Conditional mean weight must be finite and in [0,1]")
    if draws == 1 and weight:
        raise ValueError("Conditional mean loss requires two independent noise views")
    expected = POLICY if draws == 2 else None
    if config.get("noise_pair_policy", expected) != expected:
        raise ValueError("Unknown independent-noise policy")
    return draws, float(weight)


def require_resume_noise_pairs(previous, current):
    if noise_pair_options(previous) != noise_pair_options(current):
        raise ValueError(
            "Resume independent-noise policy or mean weight differs; initialize a new run"
        )


def independent_noise_view(batch, *, seed, step, domain):
    """Reuse clean geometry/camera/profile, drawing only a new sensor observation.

    Layout is [all original views, all second views]. A local generator leaves
    model/data RNG unchanged. Real paired observations must never enter here.
    """
    if domain not in ("commons", "native"):
        raise ValueError("Independent noise views require simulated-noise targets")
    required = {
        "packed",
        "variance",
        "sensor_target",
        "colors",
        "wb",
        "matrix",
        "shot",
        "read",
        "adc_black_level",
        "adc_bit_depth",
        "target",
    }
    if not required <= batch.keys() or {"sensor_reference", "sensor_mask"} & batch.keys():
        raise ValueError("Independent noise requires retained clean sensor and ADC metadata")
    size = len(batch["packed"])
    if size < 1 or any(not isinstance(v, torch.Tensor) or len(v) != size for v in batch.values()):
        raise ValueError("Independent noise fields need matching example axes")
    if not torch.all(batch["adc_bit_depth"] == 16):
        raise ValueError("Independent noise policy requires the recorded 16-bit ADC")
    device = batch["packed"].device
    value = int.from_bytes(
        hashlib.sha256(f"{POLICY}:{seed}:{step}:{domain}:view1".encode()).digest()[:8], "little"
    ) % (2**63)
    generator = torch.Generator(device=device).manual_seed(value)
    with torch.autocast(device.type, enabled=False), ieee_fp32():
        second = add_noise(
            mosaic(batch["sensor_target"].float(), batch["colors"]),
            batch["shot"],
            batch["read"],
            black_level=batch["adc_black_level"],
            bit_depth=16,
            generator=generator,
        )
        second_variance = variance_map(second, batch["shot"], batch["read"])
    result = {
        key: torch.cat(
            (v, second if key == "packed" else second_variance if key == "variance" else v)
        )
        for key, v in batch.items()
    }
    result["noise_pair_id"] = torch.arange(size, device=device).repeat(2)
    result["noise_view"] = torch.cat(
        (
            torch.zeros(size, dtype=torch.long, device=device),
            torch.ones(size, dtype=torch.long, device=device),
        )
    )
    return result


def validate_noise_pair_batch(batch):
    size = len(batch["target"])
    if size < 2 or size % 2:
        raise ValueError("Expected two equally sized independent-noise views")
    half = size // 2
    device = batch["target"].device
    if (
        "noise_pair_id" not in batch
        or "noise_view" not in batch
        or not torch.equal(batch["noise_pair_id"], torch.arange(half, device=device).repeat(2))
        or not torch.equal(
            batch["noise_view"], torch.arange(2, device=device).repeat_interleave(half)
        )
    ):
        raise ValueError("Independent-noise pair identity/layout differs")
    for key in (
        "target",
        "sensor_target",
        "colors",
        "wb",
        "matrix",
        "shot",
        "read",
        "adc_black_level",
        "adc_bit_depth",
    ):
        if (
            key not in batch
            or len(batch[key]) != size
            or not torch.equal(batch[key][:half], batch[key][half:])
        ):
            raise ValueError(f"Independent-noise pair {key} differs")
    if "sensor_reference" in batch or "sensor_mask" in batch:
        raise ValueError("Real paired observations cannot use conditional-mean supervision")
    return half


def conditional_mean_reconstruction_loss(
    prediction, batch, auxiliary=None, *, weight=0.0, **options
):
    """Convex mixture of per-view and mean-prediction reconstruction losses.

    Mean predictions are camera-linear outputs, not changed input noise
    conditioning. The original loss and its weights/masks remain unchanged.
    """
    noise_pair_options({"noise_pair_draws": 2, "conditional_mean_weight": weight})
    if weight:
        half = validate_noise_pair_batch(batch)
        if len(prediction) != 2 * half or (auxiliary is not None and len(auxiliary) != 2 * half):
            raise ValueError("Predictions and independent noise pairs differ")
    ordinary, terms = reconstruction_loss(prediction, batch, auxiliary, **options)
    if weight == 0:
        return ordinary, terms
    # Packed observations/variance are not a fictitious averaged sensor input.
    supervision = {
        key: value[:half]
        for key, value in batch.items()
        if key not in {"packed", "variance", "noise_pair_id", "noise_view"}
    }
    with torch.autocast(prediction.device.type, enabled=False), ieee_fp32():
        mean = (prediction[:half].float() + prediction[half:].float()) * 0.5
        mean_aux = (
            None
            if auxiliary is None
            else (auxiliary[:half].float() + auxiliary[half:].float()) * 0.5
        )
        averaged, mean_terms = reconstruction_loss(mean, supervision, mean_aux, **options)
        loss = (1 - weight) * ordinary + weight * averaged
        mixed = {
            key: (1 - weight) * value + weight * mean_terms[key] for key, value in terms.items()
        }
    return loss, {**mixed, "per_view_loss": ordinary, "conditional_mean_loss": averaged}

"""Resumable bounded-memory training with EMA and deterministic held-out crops."""

import hashlib
