                if noise_draws == 2 and not use_pair:
                    trace_size = len(prediction) // 2
                    source_observer(
                        data_step,
                        domain,
                        clean,
                        prediction[:trace_size],
                        None if auxiliary is None else auxiliary[:trace_size],
                        {k: v[:trace_size] for k, v in loss_batch.items()},
                    )
                else:
                    source_observer(data_step, domain, clean, prediction, auxiliary, loss_batch)
            with (
                ieee_fp32()
                if precision == "float32"
                or model.refiner is not None
                or model.coarse_refiner is not None
                or model.pyramid_refiner is not None
                or model.config.restoration_backbone in ("pretrained-rgb", "packed-isotropic")
                else nullcontext()
            ):
                loss.backward()
                grad_norm = torch.nn.utils.clip_grad_norm_(
                    model.parameters(), 1, error_if_nonfinite=True
                )
        optimizer.step()
        update_ema(
            model,
            ema,
            min(config.get("ema_decay", 0.999), (1 + step) / (10 + step)),
            trainable_only=late_only or frequency_only or global_only,
        )
        if log_step:
            metrics = {
                "event": "train",
                "step": step,
                "loss": loss.item(),
                "lr": lr,
                "grad_norm": float(grad_norm),
                "seconds_per_step": (time.perf_counter() - started) / (step - first),
                "cuda_gb": torch.cuda.max_memory_allocated() / 1e9 if device.type == "cuda" else 0,
                "domain": "mixed"
                if groups > 1
                else (
                    "paired-RAW"
                    if use_pair
                    else "native-RAW-synthetic"
                    if use_native
                    else "synthetic"
                ),
                **{key: value.item() for key, value in terms.items()},
            }
            if groups > 1:
                metrics.update(
                    data_step_start=selection[0][0],
                    data_step_end=selection[-1][0],
                    example_draws=step * groups * batch_size,
                    effective_batch_size=groups * batch_size,
                    optimizer_batch_groups=groups,
                    optimizer_forward_groups=forward_groups,
                    source_groups=observations,
                )
            if fingerprint is not None:
                metrics["batch_sha256"] = fingerprint
            if noise_draws == 2:
                metrics.update(
                    unique_context_batch_size=len(
                        clean["rgb"]
                        if domain == "commons"
                        else clean["camera_rgb"]
                        if use_native
                        else clean["packed"]
                    ),
                    forward_observation_batch_size=len(prediction),
                    independent_noise_draws=1 if use_pair else 2,
                    conditional_mean_weight_applied=0.0 if use_pair else mean_weight,
                )
            if normalization_mask is not None:
                metrics["normalization_mask"] = normalization_mask.tolist()
            if training_context:
                metrics.update(
                    context_source_size=training_context.source_size,
                    context_forward_size=training_context.forward_size,
                    context_loss_size=training_context.loss_size,
                )
                if config.get("trace_observations", False):
                    metrics.update(
                        context_forward_sha256=batch_fingerprint(forward_batch),
                        context_supervision_sha256=batch_fingerprint(loss_batch),
                    )
            with (run / "metrics.jsonl").open("a") as log:
                log.write(json.dumps(metrics) + "\n")
            print(json.dumps(metrics), flush=True)
        if step % checkpoint_interval == 0 or step == steps:
            # Temporarily apply EMA in-place; do not duplicate the frozen model.
            current = {k: v.detach().clone() for k, v in model.restoration_state_dict().items()}
            model.load_state_dict(ema, strict=False)
            scores = evaluate(
                model,
                validation,
                device,
                max_batches=config.get("val_batches", 16),
                amp=amp,
                physical_fp32=model.config.physical_fp32,
                precision=precision,
            )
            if config.get("validation_protocol"):
                from .suite import evaluate_panel

                panel_data = CleanDataset(
                    validation_manifest,
                    split="val",
                    patch_size=config.get("validation_patch_size", config.get("patch_size", 256)),
                    records=validation_records,
                    native_crop=True,
                )
                scores.update(
                    evaluate_panel(
                        model,
                        panel_data,
                        config["validation_protocol"],
                        device,
                        images=config.get("validation_images", 16),
                        batch_size=batch_size,
                        amp=amp,
                        precision=precision,
                    )
                )
            model.load_state_dict(current, strict=False)
            del current
            metrics = {"event": "validation", "step": step, **scores}
            with (run / "metrics.jsonl").open("a") as log:
                log.write(json.dumps(metrics) + "\n")
            print(json.dumps(metrics), flush=True)
            monitored = (
                scores["panel_srgb_psnr"]
                if config.get("validation_protocol")
                else scores["srgb_psnr"]
            )
            improved = monitored > best
            best = max(best, monitored)
            save_checkpoint(run / "last.pt", model, optimizer, ema, step, config, best)
            if improved:
                save_checkpoint(run / "best.pt", model, optimizer, ema, step, config, best)
        if stop_after and step - first >= stop_after:
            save_checkpoint(run / "last.pt", model, optimizer, ema, step, config, best)
            break
    return run / "last.pt"

"""Measured-CFA supervision from a separate, verified real RAW training split."""

import hashlib
import json
import math
import random
from pathlib import Path

import numpy as np
import torch
from torch.nn import functional as F
from torch.utils.data import Dataset

from .cfa import color_indices, mosaic, pack
from .color import render
from .losses import image_log_mse, multiscale_sensor_loss, validate_reconstruction_objective
from .noise import variance_map
from .paired import TRAINING_SCENES
from .paired_admission import approved_extension_cases, case_key


def paired_step(step, seed, fraction):
    # Independent of worker scheduling, global RNG and the number of prior draws.
    return random.Random(f"paired:{seed}:{step}").random() < fraction


def transform(value, turns, flip):
    value = torch.rot90(value, turns, (-2, -1))
    return value.flip(-1) if flip else value


def normalized_camera_weights(value):
    """Canonical positive camera probabilities; None keeps legacy scene sampling."""
    if value is None:
        return None
    if not isinstance(value, dict) or not value:
        raise ValueError("Paired camera sampling requires a nonempty camera/weight mapping")
    if any(not isinstance(name, str) or not name.strip() for name in value):
        raise ValueError("Paired camera sampling requires nonempty camera names")
    if any(
        isinstance(weight, bool) or not isinstance(weight, (int, float))
        or not math.isfinite(weight) or weight <= 0
        for weight in value.values()
    ):
        raise ValueError("Paired camera sampling weights must be positive finite numbers")
    try:
        total = math.fsum(value.values())
    except OverflowError as error:
        raise ValueError("Paired camera sampling weight total must be finite") from error
    if not math.isfinite(total):
        raise ValueError("Paired camera sampling weight total must be finite")
    result = {name: value[name] / total for name in sorted(value)}
    if any(weight == 0 for weight in result.values()):
        raise ValueError("Paired camera sampling weights underflow after normalization")
    return result


class PairedDataset(Dataset):
    def __init__(self, manifest, *, patch_size=256, seed=42, camera_sampling_weights=None):
        self.camera_sampling_weights = normalized_camera_weights(camera_sampling_weights)
        self.path = Path(manifest)
        self.payload = self.path.read_bytes()
        self.sha256 = hashlib.sha256(self.payload).hexdigest()
        data = json.loads(self.payload)
        if data["split"] != "train":
            raise ValueError("Paired training requires an explicitly separate train manifest")
        if patch_size < 32 or patch_size % 16:
            raise ValueError("Paired patch size must be >=32 and divisible by 16")
        approved = approved_extension_cases(data)
        seen_extensions = set()
        self.size, self.seed, self.scenes = patch_size, seed, {}
        for case in data["cases"]:
            key = case_key(case)
            reviewed = approved.get(key)
            valid_source = (
                case["scene"] in TRAINING_SCENES and case.get("paired_source_family") is None
            ) or case == reviewed
            if not valid_source or case.get("unknown_sensor"):
                raise ValueError("Paired training manifest contains a protected/unknown scene")
            if reviewed is not None:
                if key in seen_extensions:
                    raise ValueError("Repeated reviewed paired case")
                seen_extensions.add(key)
            if not case["crops"]:
                continue
            for crop in case["crops"]:
                path = self.path.parent / crop["path"]
                with path.open("rb") as handle:
                    digest = hashlib.file_digest(handle, "sha256").hexdigest()
                if digest != crop["sha256"]:
                    raise ValueError(f"Paired training crop checksum mismatch: {path}")
            group = (
                reviewed.get("scene_group", case["scene"])
                if reviewed is not None
                else case["scene"]
            )
            self.scenes.setdefault(group, []).append(case)
        if seen_extensions != set(approved):
            raise ValueError("Paired training manifest omits reviewed extension cases")
        self.names = sorted(self.scenes)
        if not self.names:
            raise ValueError("Paired training has no usable scenes")
        self.camera_scenes = {}
        if self.camera_sampling_weights is not None:
            for name in self.names:
                cameras = {case["metadata"].get("camera") for case in self.scenes[name]}
                if len(cameras) != 1 or not all(isinstance(c, str) and c for c in cameras):
                    raise ValueError("Each weighted paired scene group must have one camera")
                self.camera_scenes.setdefault(next(iter(cameras)), []).append(name)
            if set(self.camera_sampling_weights) != set(self.camera_scenes):
                raise ValueError("Paired camera sampling weights must cover exactly the dataset cameras")
            self.camera_names = sorted(self.camera_scenes)
            self.camera_probabilities = [self.camera_sampling_weights[c] for c in self.camera_names]

    def _sample_scene(self, rng):
        if self.camera_sampling_weights is None:
            return self.names[rng.randrange(len(self.names))]
        camera = rng.choices(self.camera_names, weights=self.camera_probabilities, k=1)[0]
        names = self.camera_scenes[camera]
        return names[rng.randrange(len(names))]

    def __len__(self):
        return len(self.names)

    def __getitem__(self, index):
        rng = random.Random(self.seed + index)
        scene = self._sample_scene(rng)
        case = rng.choice(self.scenes[scene])
        crop = rng.choice(case["crops"])
        with np.load(self.path.parent / crop["path"], allow_pickle=False) as arrays:
            raw = arrays["raw"]
            h, w = raw.shape
            if min(h, w) < self.size:
                raise ValueError("Prepared paired crop is smaller than the training patch")
            mask = arrays["sensor_mask"].astype(bool)
            # Reference-defined invalid regions may be skipped during training.
            positions = [
                (
                    rng.randrange((h - self.size) // 2 + 1) * 2,
                    rng.randrange((w - self.size) // 2 + 1) * 2,
                )
                for _ in range(8)
            ] + [(y, x) for y in (0, h - self.size) for x in (0, w - self.size)]
            usable = [
                (y, x)
                for y, x in positions
                if mask[:, y : y + self.size, x : x + self.size].sum() >= self.size**2 / 4
            ]
            if not usable:
                raise ValueError("Prepared crop has insufficient valid paired training samples")
            y, x = usable[0]
            region = (..., slice(y, y + self.size), slice(x, x + self.size))
            values = {
                "raw": torch.from_numpy(raw[region].copy()),
                "target": torch.from_numpy(arrays["reference_rgb"][region].copy()),
                "sensor_reference": torch.from_numpy(arrays["sensor_reference"][region].copy()),
                "sensor_mask": torch.from_numpy(mask[region].copy()),
            }
        turns, flip = rng.randrange(4), rng.random() < 0.5
        values = {k: transform(v, turns, flip).contiguous() for k, v in values.items()}
        meta = case["metadata"]
        colors = transform(color_indices(meta["pattern"]).reshape(2, 2), turns, flip).flatten()
        packed = pack(values.pop("raw")[None, None])[0]
        shot = torch.tensor(case["conditioning"]["shot"]).reshape(1, 1, 1)
        read = torch.tensor(case["conditioning"]["read"]).reshape(1, 1, 1)
        return {
            **values,
            "packed": packed,
            "variance": variance_map(packed, shot, read),
            "colors": colors,
            "wb": torch.tensor(meta["white_balance"], dtype=torch.float32),
            "matrix": torch.tensor(meta["camera_to_srgb"], dtype=torch.float32),
            "shot": shot,
            "read": read,
        }


def masked_charbonnier(error, mask):
    return (error.float().square() + 1e-8).sqrt().masked_fill(
        ~mask, 0
    ).sum() / mask.sum().clamp_min(1)


def paired_reconstruction_loss(
    prediction, batch, auxiliary=None, *, multiscale_sensor_weight=0.0,
    objective="charbonnier-v1",
):
    """Measured samples determine detail; AHD supplies only coarse RGB color.

    The 4x4 spatial means avoid supervising the network with AHD's fine-scale
    interpolation artifacts. Reference saturation masks apply to both losses.
    Independent low-ISO reference noise remains a limitation of real pairs.
    """
    validate_reconstruction_objective(objective)
    if not math.isfinite(multiscale_sensor_weight) or multiscale_sensor_weight < 0:
        raise ValueError("Multiscale sensor loss weight must be finite and nonnegative")
    reference, valid = batch["sensor_reference"], batch["sensor_mask"].bool()
    penalty = image_log_mse if objective == "image-log-mse-v1" else masked_charbonnier
    sensor = penalty(prediction - reference, valid)
    coarse_valid = F.avg_pool2d(valid.any(1, keepdim=True).float(), 4, 4) >= 0.999
    coarse_prediction = F.avg_pool2d(prediction.float(), 4, 4)
    coarse_reference = F.avg_pool2d(batch["target"].float(), 4, 4)
    display = render(coarse_prediction, batch["wb"], batch["matrix"])
    truth = render(coarse_reference, batch["wb"], batch["matrix"])
    coarse = penalty(display - truth, coarse_valid.expand_as(display))
    auxiliary_loss = prediction.new_zeros(())
    if auxiliary is not None:
        auxiliary_loss = masked_charbonnier(
            auxiliary - mosaic(reference, batch["colors"]), mosaic(valid, batch["colors"])
        )
    loss = sensor + 0.5 * coarse + 0.1 * auxiliary_loss
    terms = {
        "paired_sensor": sensor,
        "paired_coarse_rendered": coarse,
        "paired_auxiliary": auxiliary_loss,
    }
    if multiscale_sensor_weight:
        multiscale = multiscale_sensor_loss(prediction, batch)
        loss = loss + multiscale_sensor_weight * multiscale
        terms["multiscale_sensor"] = multiscale
    return loss, terms

"""Explicit training scope for the optional global RAW branch."""


def validate_raw_global_only(config):
    value = config.get("raw_global_only", False)
    if type(value) is not bool:
        raise ValueError("RAW global-only training must be a boolean")
    if value and any(
        config.get(key, False)
        for key in (
            "raw_kernel_only",
            "refiner_only",
            "coarse_refiner_only",
            "pyramid_refiner_only",
            "late_rgb_only",
            "raw_frequency_only",
        )
    ):
        raise ValueError("RAW global-only training cannot combine with another head-only mode")
    if value and config.get("model", {}).get("raw_global_features") is not True:
        raise ValueError("RAW global-only training requires RAW global features")
    return value


def require_resume_raw_global_scope(previous, current):
    if validate_raw_global_only(previous) != validate_raw_global_only(current):
        raise ValueError("Resume RAW global training scope differs; initialize a new run")

"""Optional evaluation adapter for separately acquired RawNIND reference code."""

import importlib.util
import sys
import types
from pathlib import Path

import torch
from torch import nn
from torch.nn import functional as F

from .cfa import PATTERNS, mosaic, pack, unpack


def publisher_input_scale(white_levels, black_levels, adc_white_level):
    """Convert our per-phase camera-white units to upstream global-ADC units."""
    if adc_white_level is None or len(white_levels) != 4 or len(black_levels) != 4:
        raise ValueError("Four phase levels and the global ADC white level are required")
    if any(adc_white_level <= b or w <= b for w, b in zip(white_levels, black_levels)):
        raise ValueError("Invalid RAW normalization levels")
    return [(w - b) / (adc_white_level - b) for w, b in zip(white_levels, black_levels)]


class RawNind(nn.Module):
    def __init__(self, network, gain_mode="input-mean", *, input_scale=None, clip_input=False):
        super().__init__()
        if gain_mode not in ("input-mean", "cfa-ls", "cfa-channel"):
            raise ValueError("Unknown gain matching method")
        self.network = network.eval()
        self.gain_mode = gain_mode
        self.clip_input = clip_input
        self.register_buffer(
            "input_scale",
            None
            if input_scale is None
            else torch.as_tensor(input_scale, dtype=torch.float32).reshape(4),
            persistent=False,
        )

    def forward(self, packed, variance, colors, wb=None, matrix=None):
        if colors.ndim == 1:
            colors = colors[None].expand(packed.shape[0], -1)
        outputs = []
        flips = {"RGGB": (), "BGGR": (-2, -1), "GRBG": (-1,), "GBRG": (-2,)}
        patterns = {tuple(value): name for name, value in PATTERNS.items()}
        # Normalize the actual mosaic geometry, not just channel names: RGB
        # PixelShuffle's spatial phase is part of the pretrained model contract.
        for sample, labels in zip(packed, colors):
            pattern = patterns[tuple(labels.tolist())]
            prepared = sample.float()
            if self.input_scale is not None:
                prepared = prepared * self.input_scale.to(prepared)[:, None, None]
            if self.clip_input:
                prepared = prepared.clamp(0, 1)
            raw = unpack(prepared[None])
            if flips[pattern]:
                raw = raw.flip(flips[pattern])
            canonical = pack(raw)
            h, w = canonical.shape[-2:]
            canonical = F.pad(canonical, (0, -w % 16, 0, -h % 16), mode="replicate")
            with torch.autocast(device_type=packed.device.type, enabled=False):
                output = self.network(canonical.float())[..., : 2 * h, : 2 * w]
            if flips[pattern]:
                output = output.flip(flips[pattern])
            if self.gain_mode == "input-mean":
                denominator = output.mean()
                measured = sample.clamp(0, 1) if self.clip_input else sample
                gain = measured.mean() / torch.where(
                    denominator.abs() > 1e-12, denominator, denominator.new_ones(())
                )
            else:
                observed = mosaic(output, labels[None])
                if self.gain_mode == "cfa-ls":
                    gain = (observed * sample[None]).sum() / observed.square().sum().clamp_min(
                        1e-12
                    )
                else:
                    gains = []
                    for channel in range(3):
                        mask = (labels == channel)[None, :, None, None]
                        gains.append(
                            (observed * sample[None] * mask).sum()
                            / (observed.square() * mask).sum().clamp_min(1e-12)
                        )
                    gain = torch.stack(gains)[None, :, None, None]
            outputs.append(output * gain)
        return torch.cat(outputs)


def load_rawnind(
    directory, *, gain_mode="input-mean", device="cpu", input_scale=None, clip_input=False
):
    directory = Path(directory)
    state = torch.load(directory / "utnet2-bayer.pt", map_location="cpu", weights_only=True)
    if not isinstance(state, dict):
        raise TypeError("Expected a RawNIND Bayer UtNet2 state dictionary")
    # Released Bayer variants share the UtNet2 body. Their first and last
    # convolutions identify the width and whether upsampling precedes the CNN.
    first = state.get("convs1.0.weight")
    last = state.get("output_module.0.weight")
    if (
        not isinstance(first, torch.Tensor)
        or first.ndim != 4
        or tuple(first.shape[1:]) != (4, 3, 3)
        or first.shape[0] < 1
        or not isinstance(last, torch.Tensor)
        or last.ndim != 4
        or tuple(last.shape[1:]) != (first.shape[0], 1, 1)
        or last.shape[0] not in (3, 12)
    ):
        raise ValueError("Unsupported RawNIND Bayer UtNet2 checkpoint geometry")
    configuration = {
        "in_channels": 4,
        "funit": first.shape[0],
        "activation": "LeakyReLU",
        "preupsample": last.shape[0] == 3,
    }
    # The imported upstream module only uses rawproc in a separate Passthrough
    # class. Avoid importing its entire research training dependency stack.
    names = ("rawnind", "rawnind.libs", "rawnind.libs.rawproc")
    previous = {name: sys.modules.get(name) for name in names}
    try:
        for name in names:
            sys.modules[name] = types.ModuleType(name)
        spec = importlib.util.spec_from_file_location(
            "demosaic_rawnind_reference", directory / "raw_denoiser.py"
        )
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
    finally:
        for name, value in previous.items():
            if value is None:
                sys.modules.pop(name, None)
            else:
                sys.modules[name] = value
    network = module.UtNet2(**configuration)
    network.load_state_dict(state, strict=True)
    reference = (
        RawNind(network, gain_mode, input_scale=input_scale, clip_input=clip_input)
        .to(device)
        .eval()
    )
    reference.reference_config = configuration
    return reference

"""Learning-rate policy for a newly initialized local RAW attention branch."""

import math


def spatial_lr_multiplier(config):
    value = config.get("raw_spatial_lr_multiplier", 1.0)
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(  # noqa: TRY004 -- configuration errors use ValueError before model construction
            "Spatial learning-rate multiplier must be finite and positive"
        )
    value = float(value)
    if not math.isfinite(value) or value <= 0:
        raise ValueError("Spatial learning-rate multiplier must be finite and positive")
    if value != 1:
        if config.get("model", {}).get("raw_spatial_features") is not True:
            raise ValueError("Spatial learning-rate multiplier requires RAW spatial features")
        if any(
            config.get(key, 1) != 1
            for key in (
                "phase_lr_multiplier",
                "raw_directional_lr_multiplier",
                "raw_spectral_lr_multiplier",
                "raw_frequency_lr_multiplier",
                "late_rgb_lr_multiplier",
            )
        ):
            raise ValueError(
                "Spatial learning-rate groups cannot combine with other RAW-head groups"
            )
    return value


def require_resume_spatial_lr(previous, current):
    if spatial_lr_multiplier(previous) != spatial_lr_multiplier(current):
        raise ValueError("Resume spatial learning rate differs; initialize a new run")

"""Spatial-phase Bayer packing. Phases always mean TL, TR, BL, BR, not RGGB."""

import torch
from torch import Tensor
from torch.nn import functional as F

from .precision import ieee_fp32

PATTERNS = {"RGGB": (0, 1, 1, 2), "BGGR": (2, 1, 1, 0), "GRBG": (1, 0, 2, 1), "GBRG": (1, 2, 0, 1)}


def color_indices(pattern: str, *, device=None) -> Tensor:
    try:
        return torch.tensor(PATTERNS[pattern.upper()], device=device, dtype=torch.long)
    except KeyError:
        raise ValueError(
            f"Unsupported CFA {pattern!r}; expected one of {tuple(PATTERNS)}"
        ) from None


def pack(mosaic: Tensor) -> Tensor:
    """B×1×H×W -> B×4×H/2×W/2. Input dimensions must be even."""
    if mosaic.ndim != 4 or mosaic.shape[1] != 1:
        raise ValueError("Expected B×1×H×W mosaic")
    if mosaic.shape[-2] % 2 or mosaic.shape[-1] % 2:
        raise ValueError("Bayer packing requires even dimensions")
    return F.pixel_unshuffle(mosaic, 2)


def unpack(packed: Tensor) -> Tensor:
    if packed.ndim != 4 or packed.shape[1] != 4:
        raise ValueError("Expected B×4×H×W packed Bayer")
    return F.pixel_shuffle(packed, 2)


def mosaic(rgb: Tensor, colors: Tensor) -> Tensor:
    """Sample linear camera RGB at the specified per-batch CFA phases."""
    if colors.ndim == 1:
        colors = colors.unsqueeze(0).expand(rgb.shape[0], -1)
    # unshuffle groups all four spatial phases for each RGB channel.
    phases = F.pixel_unshuffle(rgb, 2).reshape(
        rgb.shape[0], 3, 4, rgb.shape[-2] // 2, rgb.shape[-1] // 2
    )
    return phases.gather(
        1, colors[:, None, :, None, None].expand(-1, 1, -1, phases.shape[-2], phases.shape[-1])
    ).squeeze(1)


def adc_cfa_projection(
    prediction: Tensor, packed: Tensor, colors: Tensor, wb=None, *, mode="malvar"
) -> Tensor:
    """Enforce nonclipped ADC-only samples; caller must ensure shot=read=0.

    ``malvar`` retains the Malvar nullspace component with P+K(y-A(P)).
    ``sites`` replaces only valid observed RGB channels, retaining every other
    channel bit-for-bit. Both preserve near-black/clipped measured channels.
    No target fitting or output clamp is used. Enforcing noisy observations
    would inject noise.
    """
    if mode not in ("malvar", "sites"):
        raise ValueError("ADC CFA projection mode must be malvar or sites")
    if packed.ndim != 4 or packed.shape[1] != 4:
        raise ValueError("Expected four packed CFA phases")
    if prediction.shape != (packed.shape[0], 3, packed.shape[2] * 2, packed.shape[3] * 2):
        raise ValueError("Prediction and CFA dimensions disagree")
    with torch.autocast(device_type=prediction.device.type, enabled=False), ieee_fp32():
        prediction, packed = prediction.float(), packed.float()
        valid = (packed > 1 / 65535) & (packed < 1 - 1 / 65535)
        if mode == "sites":
            batch, _, height, width = packed.shape
            if colors.ndim == 1:
                colors = colors[None].expand(batch, -1)
            phases = F.one_hot(colors, 3).permute(0, 2, 1)[..., None, None]
            values = F.pixel_shuffle(
                (packed[:, None] * phases).reshape(batch, 12, height, width), 2
            )
            mask = F.pixel_shuffle(
                (valid[:, None] * phases).reshape(batch, 12, height, width), 2
            ).bool()
            return torch.where(mask, values, prediction)
        residual = (packed - mosaic(prediction, colors)) * valid
        return prediction + malvar(residual, colors, wb)


def bilinear(packed: Tensor, colors: Tensor, *, fp32=True) -> Tensor:
    """Normalized interpolation, kept in FP32 even inside network autocast."""
    if fp32:
        with (
            torch.autocast(device_type=packed.device.type, enabled=False),
            ieee_fp32(),
        ):
            return _bilinear(packed.float(), colors)
    return _bilinear(packed, colors)


def _bilinear(packed, colors):
    batch, _, height, width = packed.shape
    if colors.ndim == 1:
        colors = colors[None].expand(batch, -1)
    masks = F.one_hot(colors, 3).to(packed.dtype).permute(0, 2, 1)[..., None, None]
    sparse = F.pixel_shuffle((packed[:, None] * masks).reshape(batch, 12, height, width), 2)
    mask = F.pixel_shuffle(
        masks.expand(-1, -1, -1, height, width).reshape(batch, 12, height, width), 2
    )
    kernel = packed.new_tensor([[1, 2, 1], [2, 4, 2], [1, 2, 1]])[None, None]
    kernel = kernel.expand(3, 1, 3, 3)
    numerator = F.conv2d(F.pad(sparse, (1, 1, 1, 1), mode="replicate"), kernel, groups=3)
    denominator = F.conv2d(F.pad(mask, (1, 1, 1, 1), mode="replicate"), kernel, groups=3)
    result = numerator / denominator.clamp_min(1e-8)
    return torch.where(mask.bool(), sparse, result)


def malvar(packed: Tensor, colors: Tensor, wb=None) -> Tensor:
    """FP32 Malvar-He-Cutler 5×5 linear demosaicing (ICASSP 2004, Fig. 2).

    Independently implemented from the published filters, with phase-preserving
    reflected borders. A classical comparator, not a trained denoiser.
    """
    with (
        torch.autocast(device_type=packed.device.type, enabled=False),
        ieee_fp32(),
    ):
        packed = packed.float()
        batch, _, height, width = packed.shape
        if min(height, width) < 2:
            raise ValueError("Malvar interpolation requires at least a 4×4 mosaic")
        if colors.ndim == 1:
            colors = colors[None].expand(batch, -1)
        if wb is not None:
            wb = torch.as_tensor(wb, device=packed.device, dtype=torch.float32).reshape(-1, 3)
            wb = wb.expand(batch, -1).clamp_min(1e-6)
            packed = packed * wb.gather(1, colors)[..., None, None]
        raw = unpack(packed)
        green = (
            packed.new_tensor(
                [
                    [0, 0, -1, 0, 0],
                    [0, 0, 2, 0, 0],
                    [-1, 2, 4, 2, -1],
                    [0, 0, 2, 0, 0],
                    [0, 0, -1, 0, 0],
                ]
            )
            / 8
        )
        horizontal = (
            packed.new_tensor(
                [
                    [0, 0, 0.5, 0, 0],
                    [0, -1, 0, -1, 0],
                    [-1, 4, 5, 4, -1],
                    [0, -1, 0, -1, 0],
                    [0, 0, 0.5, 0, 0],
                ]
            )
            / 8
        )
        diagonal = (
            packed.new_tensor(
                [
                    [0, 0, -1.5, 0, 0],
                    [0, 2, 0, 2, 0],
                    [-1.5, 0, 6, 0, -1.5],
                    [0, 2, 0, 2, 0],
                    [0, 0, -1.5, 0, 0],
                ]
            )
            / 8
        )
        kernels = torch.stack((green, horizontal, horizontal.T, diagonal))[:, None]
        g, horizontal, vertical, diagonal = F.conv2d(
            F.pad(raw, (2, 2, 2, 2), mode="reflect"), kernels
        ).split(1, dim=1)
        labels = F.one_hot(colors, 3).permute(0, 2, 1)[..., None, None]
        masks = F.pixel_shuffle(
            labels.expand(-1, -1, -1, height, width).reshape(batch, 12, height, width).float(), 2
        ).bool()
        parity = torch.arange(height * 2, device=packed.device)[None, :, None] % 2
        red_row = ((colors == 0).long().argmax(1) // 2)[:, None, None]
        blue_row = ((colors == 2).long().argmax(1) // 2)[:, None, None]
        red = torch.where((parity == red_row)[:, None], horizontal, vertical)
        blue = torch.where((parity == blue_row)[:, None], horizontal, vertical)
        red = torch.where(masks[:, 0:1], raw, torch.where(masks[:, 2:3], diagonal, red))
        blue = torch.where(masks[:, 2:3], raw, torch.where(masks[:, 0:1], diagonal, blue))
        result = torch.cat((red, torch.where(masks[:, 1:2], raw, g), blue), dim=1)
        return result if wb is None else result / wb[..., None, None]

"""Preserve photographic source draws when curating a subset of a frozen corpus."""

import hashlib
import json
import os
from pathlib import Path


class PhotoSamplingReference:
    """Uniform rejection sampling from an immutable, ordered training-source list.

    Draw the initial identity before checking a reviewed ROI override. Only a
    non-overridden excluded identity consumes retry draws; every other source
    and subsequent geometry RNG state remain identical to the original reader.
    """

    def __init__(self, reference, manifest, rows, *, expected_sha256=None):
        self.path = Path(reference)
        payload = self.path.read_bytes()
        self.sha256 = hashlib.sha256(payload).hexdigest()
        if expected_sha256 is not None and self.sha256 != expected_sha256:
            raise ValueError("Photo sampling reference changed after its training snapshot")
        self.rows = {row["id"]: row for row in rows}
        if not self.rows or len(self.rows) != len(rows):
            raise ValueError("Photo sampling requires nonempty unique active training sources")
        if any(row["split"] != "train" for row in rows):
            raise ValueError("Photo sampling reference is only for training sources")
        identities, seen = [], set()
        for line in payload.splitlines():
            row = json.loads(line)
            identity = row["id"]
            if identity in seen:
                raise ValueError("Photo sampling reference contains duplicate source identities")
            seen.add(identity)
            if row["split"] != "train":
                continue
            identities.append(identity)
            current = self.rows.get(identity)
            if current is not None and (
                row != current
                or os.path.abspath(self.path.parent / row["cache"])
                != os.path.abspath(Path(manifest).parent / current["cache"])
            ):
                raise ValueError("Photo sampling reference changes an active source or cache path")
        if not identities or not self.rows.keys() <= set(identities):
            raise ValueError("Active photo sources must be a subset of the sampling reference")
        self.identities = tuple(identities)

    def initial(self, rng):
        return self.identities[rng.randrange(len(self.identities))]

    def eligible(self, identity, rng):
        while identity not in self.rows:
            identity = self.initial(rng)
        return self.rows[identity]


def require_resume_photo_sampling(previous, current):
    if previous.get("photo_sampling_reference_sha256") != current.get(
        "photo_sampling_reference_sha256"
    ):
        raise ValueError("Resume photo sampling reference differs; initialize a new run")

"""Detached per-draw diagnostics for finding problematic training photographs."""

import json

import torch

from .losses import DEFAULT_RECONSTRUCTION_EPSILON, reconstruction_loss
from .precision import ieee_fp32
from .safety import writable_path


def validate_source_loss_every(value):
    if type(value) is not int or value < 0:
        raise ValueError("source_loss_every must be a nonnegative integer")
    return value


class SourceLossTrace:
    """Score existing Commons predictions as FP32 singleton losses, without gradients.

    Singleton mask denominators differ from a batch loss. These diagnostics are
    not additive contributions to the actual training objective. High loss can
    reflect difficult noise/detail rather than bad source quality; inspect it.
    """

    def __init__(self, path, config):
        self.path = writable_path(path)
        self.options = {
            "physical_fp32": True,
            "normalized_sensor_weight": config.get("normalized_sensor_weight", 0.0),
            "multiscale_sensor_weight": config.get("multiscale_sensor_weight", 0.0),
            "objective": config.get("reconstruction_objective", "charbonnier-v1"),
            "camera_supervision": config.get("camera_supervision", "reference-white-v1"),
            "reference_interval_weight": config.get("reference_interval_weight", 0.0),
            "reconstruction_charbonnier_epsilon": config.get(
                "reconstruction_charbonnier_epsilon", DEFAULT_RECONSTRUCTION_EPSILON
            ),
            "gradient_charbonnier_epsilon": config.get("gradient_charbonnier_epsilon"),
            "normalized_band_weight": config.get("normalized_band_weight", 0.0),
        }

    @torch.no_grad()
    def __call__(self, data_step, domain, clean, prediction, auxiliary, batch, *, step):
        if domain != "commons":
            return
        size = len(prediction)
        sources = clean["source"]
        if len(sources) != size:
            raise ValueError("Source trace and predictions have different example counts")
        records = []
        with torch.autocast(prediction.device.type, enabled=False), ieee_fp32():
            for index, source in enumerate(sources):
                # All prepared supervision tensors retain their example axis.
                sample = {
                    key: value[index : index + 1].detach().float()
                    if value.is_floating_point()
                    else value[index : index + 1].detach()
                    for key, value in batch.items()
                }
                value, terms = reconstruction_loss(
                    prediction[index : index + 1].detach().float(),
                    sample,
                    None if auxiliary is None else auxiliary[index : index + 1].detach().float(),
                    **self.options,
                )
                scores = {
                    "singleton_loss_fp32": float(value),
                    "terms": {key: float(term) for key, term in terms.items()},
                }
                if not torch.isfinite(value) or any(not torch.isfinite(t) for t in terms.values()):
                    raise ValueError("Nonfinite source diagnostic")
                records.append(
                    {
                        "event": "source-loss",
                        "step": step,
                        "data_step": data_step,
                        "example_in_source_batch": index,
                        "domain": domain,
                        "source": json.loads(source),
                        **scores,
                        "noise": {
                            key: float(sample[key].reshape(-1)[0]) for key in ("shot", "read")
                        },
                        "colors": sample["colors"][0].tolist(),
                        "wb": sample["wb"][0].tolist(),
                        "matrix": sample["matrix"][0].tolist(),
                        "source_rgb_shape": list(clean["rgb"].shape[1:]),
                        "supervision_shape": list(prediction.shape[1:]),
                        "score_definition": "FP32 detached singleton reconstruction, not an additive batch-loss contribution",
                    }
                )
                if "noise_view" in sample:
                    records[-1]["source_trace_noise_view"] = int(
                        sample["noise_view"].reshape(-1)[0]
                    )
                if "shadow_exposure_selected" in sample:
                    records[-1]["reviewed_shadow_exposure"] = {
                        "selected": bool(sample["shadow_exposure_selected"].reshape(-1)[0]),
                        "requested_green_mean": float(
                            sample["shadow_requested_green"].reshape(-1)[0]
                        ),
                        "actual_exposure_gain": float(
                            sample["shadow_exposure_scale"].reshape(-1)[0]
                        ),
                    }
        # Finish all diagnostics before appending; don't leave a partial batch.
        with self.path.open("a") as stream:
            for record in records:
                stream.write(json.dumps(record, allow_nan=False) + "\n")

"""Exact Bayer rotations/reflections for optional eight-view inference."""

import torch

from .cfa import pack, unpack


def _transform(value, turns, reflected):
    value = torch.rot90(value, turns, (-2, -1))
    return (value.flip(-1) if reflected else value).contiguous()


@torch.inference_mode()
def predict_dihedral8(model, packed, variance, colors, wb=None, matrix=None):
    """Average eight predictions in camera RGB, with no resampling or fitting.

    Transform sensor samples, variances and CFA colors together. WB/matrix and
    the model's shot/read conditioning keep their original camera meanings.
    Only the current view and a float64 sum persist; return float32 before the
    caller's usual tile blending, clipping, display conversion or RGB16 export.
    """
    if getattr(model, "training", False):
        raise ValueError("Eight-view inference requires an evaluation-mode model")
    if packed.ndim != 4 or packed.shape[1] != 4 or variance.shape != packed.shape:
        raise ValueError("Expected matching B×4×H×W packed measurements and variances")
    batch = packed.shape[0]
    if colors.ndim == 1:
        colors = colors[None].expand(batch, -1)
    if colors.shape != (batch, 4):
        raise ValueError("Expected four CFA colors per image")
    raw, noise = unpack(packed), unpack(variance)
    color_tile = colors.reshape(batch, 1, 2, 2)
    total = None
    expected_shape = (batch, 3, raw.shape[-2], raw.shape[-1])
    for reflected in (False, True):
        for turns in range(4):
            prediction = model(
                pack(_transform(raw, turns, reflected)),
                pack(_transform(noise, turns, reflected)),
                _transform(color_tile, turns, reflected).reshape(batch, 4),
                wb,
                matrix,
            ).float()
            if reflected:
                prediction = prediction.flip(-1)
            prediction = torch.rot90(prediction, -turns, (-2, -1))
            if prediction.shape != expected_shape:
                raise ValueError("Restoration must return native B×3×2H×2W camera RGB")
            if total is None:
                total = prediction.double()
            else:
                total.add_(prediction)
    return total.div_(8).float()

"""Native FP32 predictions and exact supervision for later quality audits."""

import errno
import hashlib
import json
import os
import shutil
from pathlib import Path

import numpy as np

from .safety import writable_path


def _array(value):
    if hasattr(value, "detach"):
        value = value.detach().cpu().contiguous().numpy()
    result = np.asarray(value)
    if result.dtype.kind not in "buif" or not np.isfinite(result).all():
        raise ValueError("Archive arrays must be finite numeric values")
    return np.ascontiguousarray(result)


def fingerprint(value):
    """Describe logical values identically across contiguous/strided layouts."""
    array = _array(value)
    return {"shape": list(array.shape), "dtype": array.dtype.str,
            "sha256": hashlib.sha256(array.tobytes()).hexdigest()}


def _binding(path):
    with path.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    return {"path": str(path), "sha256": digest}


def _json(value):
    return json.dumps(value, sort_keys=True, allow_nan=False, separators=(",", ":"))


class PredictionArchive:
    """One exclusive evaluation writer; targets are shared across models/CFAs.

    Records become visible only after both arrays are closed and checksummed.
    A failed evaluation leaves its completed records and partial work intact.
    Model execution, observations, metrics and image transforms stay with callers.
    """

    def __init__(self, output):
        self.output = writable_path(output).absolute()
        self.output.mkdir(parents=True, exist_ok=False)
        (self.output / "predictions").mkdir()
        (self.output / "supervision").mkdir()
        self.records = []
        self._models, self._targets, self._contexts = {}, {}, {}
        self.manifest = self.output / "records.jsonl"
        self.manifest.touch(exist_ok=False)

    def append(self, model, context, prediction, supervision, *, prediction_file=None):
        """Write one native B×3×H×W result, preserving FP32 and source identity."""
        model, context = json.loads(_json(model)), json.loads(_json(context))
        digest = model.get("sha256", "")
        if len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
            raise ValueError("A model requires its exact lowercase checkpoint SHA256")
        if not model.get("label") or model.get("self_ensemble") not in {"none", "dihedral8"}:
            raise ValueError("Declare a model label and inference policy")
        identity = digest, model["self_ensemble"]
        if identity in self._models and self._models[identity] != model:
            raise ValueError("Model metadata changed during evaluation")
        values = _array(prediction)
        if values.dtype != np.float32 or values.ndim != 4 or values.shape[1] != 3 or not all(values.shape):
            raise ValueError("Predictions must be native B×3×H×W float32")
        ids = context.get("ids")
        if not isinstance(ids, list) or len(ids) != len(values) or any(not isinstance(v, str) or not v for v in ids) or len(set(ids)) != len(ids):
            raise ValueError("One distinct source/draw ID is required per prediction")
        if not context.get("input_fingerprints"):
            raise ValueError("Retain the actual input fingerprints")
        target_arrays = {name: _array(value) for name, value in supervision.items()}
        if any(not name.isidentifier() for name in target_arrays):
            raise ValueError("Supervision keys must be identifiers")
        target = target_arrays.get("target", target_arrays.get("reference_rgb"))
        if target is None or target.dtype != np.float32 or target.shape != values.shape:
            raise ValueError("Retain an exact float32 RGB target/reference at native shape")
        for name, shape in [("wb", (len(values), 3)), ("matrix", (len(values), 3, 3))]:
            if name not in target_arrays or target_arrays[name].shape != shape:
                raise ValueError("Retain per-image white balance and camera matrix")
        context_key = _json(context)
        seen = self._contexts.setdefault(identity, set())
        if context_key in seen:
            raise ValueError("Duplicate model observation")
        descriptions = {name: fingerprint(value) for name, value in sorted(target_arrays.items())}
        target_key = hashlib.sha256(_json(descriptions).encode()).hexdigest()
        if target_key not in self._targets:
            path = self.output / "supervision" / (target_key+".npz")
            with path.open("xb") as stream:
                np.savez(stream, **target_arrays)
            path.chmod(0o444)
            self._targets[target_key] = _binding(path)
        index = len(self.records)
        path = self.output / "predictions" / f"batch-{index:06d}.npy"
        if prediction_file is None:
            with path.open("xb") as stream:
                np.save(stream, values, allow_pickle=False)
            path.chmod(0o444)
        else:
            source = Path(prediction_file)
            if fingerprint(np.load(source, allow_pickle=False)) != fingerprint(values):
                raise ValueError("Existing prediction differs from the evaluated values")
            # Share bytes on one filesystem. Across filesystems, preserve the
            # original NPY bytes in an exclusive copy without touching the source.
            try:
                os.link(source, path)
            except OSError as error:
                if error.errno != errno.EXDEV:
                    raise
                with source.open("rb") as original, path.open("xb") as destination:
                    shutil.copyfileobj(original, destination)
                path.chmod(0o444)
        row = {"schema": "demosaic-predictions-v1", "index": index, "model": model,
               "context": context, "prediction": _binding(path), "prediction_values": fingerprint(values),
               "supervision": self._targets[target_key], "supervision_values": descriptions}
        with self.manifest.open("a") as stream:
            stream.write(_json(row)+"\n")
        self.records.append(row)
        self._models[identity] = model
        seen.add(context_key)
        return row

    def verify_alignment(self):
        """Require identical observations and targets across methods, irrespective of order."""
        groups = {}
        for row in self.records:
            key = row["model"]["sha256"], row["model"]["self_ensemble"]
            groups.setdefault(key, {})[_json(row["context"])] = row["supervision_values"]
        if not groups:
            raise ValueError("No predictions retained")
        first = next(iter(groups.values()))
        if any(group != first for group in groups.values()):
            raise ValueError("Methods received different observations, inputs or supervision")
        return {"models": len(groups), "observations_per_model": len(first),
                "records": len(self.records), "unique_supervision_arrays": len(self._targets)}


def iter_predictions(manifest):
    """Stream checksummed predictions and exact targets; never run a model."""
    root = Path(manifest).absolute().parent
    for index, line in enumerate(Path(manifest).read_text().splitlines()):
        row = json.loads(line)
        if row["schema"] != "demosaic-predictions-v1" or row["index"] != index:
            raise ValueError("Unexpected archive schema or record sequence")
        for key in ["prediction", "supervision"]:
            path = Path(row[key]["path"])
            if not path.resolve().is_relative_to(root.resolve()) or _binding(path) != row[key]:
                raise ValueError("Archive file path/checksum mismatch")
        prediction = np.load(row["prediction"]["path"], allow_pickle=False)
        with np.load(row["supervision"]["path"], allow_pickle=False) as archive:
            targets = {k: archive[k].copy() for k in archive.files}
        if fingerprint(prediction) != row["prediction_values"] or {k: fingerprint(v) for k, v in targets.items()} != row["supervision_values"]:
            raise ValueError("Archive logical array metadata mismatch")
        yield row, prediction, targets

"""Neighboring RAW-gradient descriptors for the memory-only global branch."""

import torch
from torch import nn
from torch.nn import functional as F

from .raw_global_memory_features import MemoryOnlyRawGlobalFeatures


def neighboring_gradients(content):
    """Eight neighboring vectors, row-major; zero outside, no center or wrap."""
    if content.ndim != 4 or content.shape[1] != 8 or min(content.shape) < 1:
        raise ValueError("Patch descriptors require nonempty Bx8xHxW signed gradients")
    height, width = content.shape[-2:]
    padded = F.pad(content, (1, 1, 1, 1))
    return torch.cat(
        [
            padded[..., y : y + height, x : x + width]
            for y in range(3)
            for x in range(3)
            if (y, x) != (1, 1)
        ],
        dim=1,
    )


class PatchMemoryRawGlobalFeatures(MemoryOnlyRawGlobalFeatures):
    """Keep the point token and learn a zero-initialized spatial addition.

    Both point and neighboring content still pass through read/write memory;
    there is no added local path to the returned stem offset. Shared tensors
    and constructor RNG stay exact. Every per-phase spatial constant remains
    zero after learning, even with spatially varying variance conditioning.
    """

    def __init__(self):
        super().__init__()
        with torch.random.fork_rng(devices=[]):
            self.patch_embed = nn.Conv2d(64, 32, 1, bias=False, device="cpu")
            nn.init.zeros_(self.patch_embed.weight)

    def embed_content(self, content):
        point = super().embed_content(content)
        patch = self.patch_embed(neighboring_gradients(content)).flatten(2).transpose(1, 2)
        return point + patch

"""Explicit scene-linear and display transforms; no hidden 8-bit conversions."""

import numpy as np
import torch

from .precision import ieee_fp32


def srgb_to_linear(x):
    if isinstance(x, np.ndarray):
        return np.where(x <= 0.04045, x / 12.92, ((x + 0.055) / 1.055) ** 2.4)
    return torch.where(x <= 0.04045, x / 12.92, ((x.clamp_min(0) + 0.055) / 1.055).pow(2.4))


def linear_to_srgb(x):
    if isinstance(x, np.ndarray):
        return np.where(x <= 0.0031308, 12.92 * x, 1.055 * np.maximum(x, 0) ** (1 / 2.4) - 0.055)
    return torch.where(x <= 0.0031308, 12.92 * x, 1.055 * x.clamp_min(1e-10).pow(1 / 2.4) - 0.055)


def render(rgb, white_balance=None, matrix=None, *, fp32=True):
    """B×3×H×W camera RGB -> clipped sRGB, for previews and display losses."""
    if fp32:
        with torch.autocast(device_type=rgb.device.type, enabled=False), ieee_fp32():
            return _render(
                rgb.float(),
                None if white_balance is None else white_balance.float(),
                None if matrix is None else matrix.float(),
            )
    return _render(rgb, white_balance, matrix)


def _render(rgb, white_balance, matrix):
    if white_balance is not None:
        rgb = rgb * white_balance[..., None, None]
    if matrix is not None:
        rgb = torch.einsum("bij,bjhw->bihw", matrix, rgb)
    return linear_to_srgb(rgb.clamp(0, 1)).clamp(0, 1)

"""Bind reviewed training-only photograph regions to their exact source data."""

import hashlib
import json
import math
import random
from dataclasses import dataclass
from pathlib import Path

import numpy as np


def validate_roi_fraction(value):
    if isinstance(value, bool):
        raise TypeError("Reviewed photographic ROI fraction must be a probability")
    value = float(value)
    if not math.isfinite(value) or not 0 <= value <= 1:
        raise ValueError("Reviewed photographic ROI fraction must be finite and within [0,1]")
    return value


def require_resume_rois(previous, current):
    if previous.get("reviewed_roi_fraction", 0.0) != current.get("reviewed_roi_fraction", 0.0):
        raise ValueError("Resume reviewed photographic ROI fraction differs; initialize a new run")
    if previous.get("reviewed_roi_catalogue_sha256") != current.get(
        "reviewed_roi_catalogue_sha256"
    ):
        raise ValueError("Resume reviewed photographic ROI catalogue differs; initialize a new run")


@dataclass(frozen=True)
class ReviewedPhotoROI:
    record: dict
    xywh: tuple[int, int, int, int]


class ReviewedPhotoROIs:
    def __init__(self, catalogue, manifest, rows, *, required_size, expected_sha256=None):
        self.path = Path(catalogue)
        self.payload = self.path.read_bytes()
        self.sha256 = hashlib.sha256(self.payload).hexdigest()
        if expected_sha256 is not None and self.sha256 != expected_sha256:
            raise ValueError("Reviewed ROI catalogue changed after its training snapshot")
        data = json.loads(self.payload)
        manifest = Path(manifest)
        reference = data["source_manifest"]
        if (
            Path(reference["path"]).resolve() != manifest.resolve()
            or reference["sha256"] != hashlib.sha256(manifest.read_bytes()).hexdigest()
        ):
            raise ValueError("Reviewed ROI source manifest differs")
        if (
            data["source_split"] != "train"
            or data["source_bin_factor"] != 4
            or data["final_area_reduction"] != 2
            or data["effective_bin_factor"] != 8
            or data["target_native_shape"] != [256, 256, 3]
        ):
            raise ValueError("Reviewed ROI catalogue must describe native8 training targets")
        by_id = {row["id"]: row for row in rows}
        if len(by_id) != len(rows):
            raise ValueError("Reviewed ROI training source identities are ambiguous")
        self.regions, seen = [], set()
        for example in data["examples"]:
            identity, source = example["id"], example["source"]
            if (
                identity in seen
                or identity not in by_id
                or source != by_id[identity]
                or source["split"] != "train"
                or source.get("bin_factor") != 4
                or source.get("dtype") != "uint16"
                or source.get("color_space") != "linear-sRGB"
            ):
                raise ValueError("Reviewed ROI must identify one exact active training source")
            seen.add(identity)
            box = example["ROI_in_bin4_xywh"]
            if len(box) != 4 or any(type(v) is not int for v in box):
                raise ValueError("Reviewed ROI coordinates must be integers")
            x, y, width, height = box
            if x < 0 or y < 0 or x % 2 or y % 2 or width != 512 or height != 512:
                raise ValueError("Reviewed ROI requires an aligned512x512 bin4 context")
            if required_size > min(width, height):
                raise ValueError(
                    "Reviewed ROI is smaller than the required native training context"
                )
            cache = manifest.parent / source["cache"]
            with cache.open("rb") as stream:
                digest = hashlib.file_digest(stream, "sha256").hexdigest()
            if digest != source["cache_sha256"]:
                raise ValueError("Reviewed ROI source cache hash changed")
            array = np.load(cache, mmap_mode="r", allow_pickle=False)
            if (
                array.dtype != np.uint16
                or array.ndim != 3
                or array.shape[-1] != 3
                or list(array.shape) != source["shape"]
                or x + width > array.shape[1]
                or y + height > array.shape[0]
            ):
                raise ValueError("Reviewed ROI cache shape/dtype or bounds differ")
            crop = array[y : y + height, x : x + width].copy()
            if hashlib.sha256(crop.tobytes()).hexdigest() != example["actual_bin4_crop_sha256"]:
                raise ValueError("Reviewed ROI pixel hash changed")
            target = crop.astype(np.float32).reshape(256, 2, 256, 2, 3).mean((1, 3)) / 65535
            if (
                hashlib.sha256(target.tobytes()).hexdigest()
                != example["native8_target_float32_sha256"]
            ):
                raise ValueError("Reviewed ROI native8 target hash changed")
            self.regions.append(ReviewedPhotoROI(by_id[identity], tuple(box)))
        if not self.regions:
            raise ValueError("Reviewed ROI catalogue has no training regions")

    def choose(self, seed, index, fraction):
        """Use an independent stream so untouched samples keep every legacy draw."""
        value = hashlib.sha256(f"reviewed-photo-roi-v1:{seed}:{index}".encode()).digest()
        rng = random.Random(int.from_bytes(value[:8], "little"))
        if rng.random() >= fraction:
            return None
        return self.regions[rng.randrange(len(self.regions))]

"""Enforce the workspace's authorized write locations."""

from pathlib import Path

REPOSITORY = Path(__file__).resolve().parents[2]


def writable_path(path) -> Path:
    path = Path(path).expanduser().resolve()
    if not any(
        path == root or root in path.parents for root in (REPOSITORY, Path("/mnt/external"))
    ):
        raise ValueError(f"Output must be inside {REPOSITORY} or /mnt/external: {path}")
    if path == Path("/mnt/external/qi") or Path("/mnt/external/qi") in path.parents:
        raise ValueError("The original Commons corpus is read-only for this project")
    return path

"""Matched central supervision with an explicitly chosen surrounding input field."""

from dataclasses import dataclass

import torch

FULL_FIELDS = frozenset({"target", "sensor_target", "sensor_reference", "sensor_mask"})
PACKED_FIELDS = frozenset({"packed", "variance"})
CONFIG_FIELDS = ("forward_patch_size", "loss_patch_size", "validation_patch_size")


def _size(value, label):
    if type(value) is not int or value < 4 or value % 2:
        raise ValueError(f"{label} must be an even native size of at least four")
    return value


def _bounds(shape, size):
    height, width = shape
    if size > min(height, width) or (height - size) % 4 or (width - size) % 4:
        raise ValueError("Central crop must fit and preserve both Bayer phase offsets")
    return (height - size) // 2, (width - size) // 2


def crop_training_batch(batch, size):
    """Crop physical samples, clean targets and masks in their own coordinate units.

    Metadata is shared unchanged; no values are interpolated or random draws made.
    Unrecognized spatial fields refuse cropping rather than retaining a larger mask.
    """
    _size(size, "Crop size")
    shape = tuple(n * 2 for n in batch["packed"].shape[-2:])
    top, left = _bounds(shape, size)
    if shape == (size, size):
        return batch
    result = {}
    half = tuple(n // 2 for n in shape)
    for key, value in batch.items():
        if key in FULL_FIELDS:
            if value.ndim != 4 or tuple(value.shape[-2:]) != shape:
                raise ValueError(f"Unexpected full-resolution field shape: {key}")
            result[key] = value[..., top : top + size, left : left + size]
        elif key in PACKED_FIELDS:
            if value.ndim != 4 or tuple(value.shape[-2:]) != half:
                raise ValueError(f"Unexpected packed-resolution field shape: {key}")
            result[key] = value[
                ..., top // 2 : (top + size) // 2, left // 2 : (left + size) // 2
            ]
        elif torch.is_tensor(value) and value.ndim >= 3 and tuple(value.shape[-2:]) in (
            shape,
            half,
        ):
            raise ValueError(f"Unrecognized spatial training field: {key}")
        else:
            result[key] = value
    return result


@dataclass(frozen=True)
class TrainingContext:
    source_size: int
    forward_size: int
    loss_size: int
    validation_size: int

    @classmethod
    def from_config(cls, config):
        if not any(key in config for key in CONFIG_FIELDS):
            return None
        source = _size(config.get("patch_size", 256), "Source patch size")
        forward = _size(config.get("forward_patch_size", source), "Forward patch size")
        loss = _size(config.get("loss_patch_size", forward), "Loss patch size")
        validation = _size(config.get("validation_patch_size", source), "Validation patch size")
        if any(size < 32 or size % 16 for size in (source, validation)):
            raise ValueError("Source/validation datasets require sizes >=32 divisible by 16")
        _bounds((source, source), forward)
        _bounds((forward, forward), loss)
        if config.get("optimizer_batch_groups", 1) != 1:
            raise ValueError("Explicit training context currently requires a single source batch")
        return cls(source, forward, loss, validation)

    def forward_batch(self, batch):
        expected = (self.source_size // 2,) * 2
        if tuple(batch["packed"].shape[-2:]) != expected:
            raise ValueError("Prepared source batch differs from declared training context")
        return crop_training_batch(batch, self.forward_size)

    def supervision(self, prediction, auxiliary, source_batch):
        if tuple(prediction.shape[-2:]) != (self.forward_size,) * 2:
            raise ValueError("Prediction differs from declared forward context")
        top, left = _bounds(prediction.shape[-2:], self.loss_size)
        prediction = prediction[..., top : top + self.loss_size, left : left + self.loss_size]
        if auxiliary is not None:
            if tuple(auxiliary.shape[-2:]) != (self.forward_size // 2,) * 2:
                raise ValueError("Auxiliary mosaic differs from declared forward context")
            auxiliary = auxiliary[
                ..., top // 2 : (top + self.loss_size) // 2,
                left // 2 : (left + self.loss_size) // 2,
            ]
        return prediction, auxiliary, crop_training_batch(source_batch, self.loss_size)


def require_resume_context(previous, current):
    before, after = TrainingContext.from_config(previous), TrainingContext.from_config(current)
    if before is None and after is None:
        return
    if before is None:
        size = previous.get("patch_size", 256)
        before = TrainingContext(size, size, size, size)
    if after is None:
        size = current.get("patch_size", 256)
        after = TrainingContext(size, size, size, size)
    if before != after:
        raise ValueError("Resume input context or central supervision geometry differs")

"""Optimizer/EMA state for the isolated readout above frozen V183 EMA."""

import copy
import hashlib

import torch


def readout_parameters(module):
    parameters = {n: p for n, p in module.named_parameters() if p.requires_grad}
    expected = {"wave_readout." + n for n, _ in module.wave_readout.named_parameters()}
    if set(parameters) != expected or len(parameters) != 4:
        raise ValueError("Only the four readout tensors may train")
    return parameters


def inherited_hash(module):
    digest = hashlib.sha256()
    for name, value in module.state_dict().items():
        if name.startswith("wave_readout."):
            continue
        value = value.detach().cpu().contiguous()
        digest.update(name.encode() + str(value.dtype).encode() + str(tuple(value.shape)).encode())
        digest.update(value.reshape(-1).view(torch.uint8).numpy().tobytes())
    return digest.hexdigest()


def fresh_state(module, *, lr, weight_decay):
    parameters = readout_parameters(module)
    optimizer = torch.optim.AdamW(parameters.values(), lr=lr, weight_decay=weight_decay)
    ema = {n: p.detach().clone() for n, p in parameters.items()}
    return optimizer, ema


def update_ema(module, ema, *, updates):
    parameters = readout_parameters(module)
    if set(ema) != set(parameters) or type(updates) is not int or updates < 1:
        raise ValueError("Expected all readout EMA tensors and a positive new-head clock")
    decay = min(0.999, (1 + updates) / (10 + updates))
    with torch.no_grad():
        for n, p in parameters.items():
            if p.shape != ema[n].shape or p.dtype != ema[n].dtype:
                raise ValueError("Readout EMA shape/dtype mismatch")
            ema[n].lerp_(p, 1 - decay)
    return decay


def load_ema(module, ema):
    parameters = readout_parameters(module)
    if set(parameters) != set(ema):
        raise ValueError("Expected exactly the four readout EMA tensors")
    with torch.no_grad():
        for n, p in parameters.items():
            if p.shape != ema[n].shape or p.dtype != ema[n].dtype:
                raise ValueError("Readout EMA shape/dtype mismatch")
            p.copy_(ema[n])


def clocks(module, optimizer):
    parameters = readout_parameters(module)
    if (
        len(optimizer.param_groups) != 1
        or len(optimizer.param_groups[0]["params"]) != 4
        or set(optimizer.param_groups[0]["params"]) != set(parameters.values())
        or set(optimizer.state) - set(parameters.values())
    ):
        raise ValueError("Optimizer must contain only readout state")
    steps = []
    for parameter in parameters.values():
        state = optimizer.state.get(parameter)
        if state:
            if not all(torch.isfinite(v).all() for v in state.values() if torch.is_tensor(v)):
                raise ValueError("Nonfinite readout Adam state")
            steps.append(float(state["step"]))
    return {"tensors": 4, "states": len(steps), "steps": sorted(set(steps))}


def restore_state(module, checkpoint, *, lr, weight_decay):
    from train_local_noise_matching_trial import tree_equal

    module.load_state_dict(checkpoint["models"], strict=True)
    optimizer, _ = fresh_state(module, lr=lr, weight_decay=weight_decay)
    optimizer.load_state_dict(copy.deepcopy(checkpoint["optimizer"]))
    assert tree_equal(optimizer.state_dict(), checkpoint["optimizer"])
    parameters = readout_parameters(module)
    assert set(checkpoint["ema"]) == set(parameters)
    ema = {n: v.detach().to(parameters[n].device).clone() for n, v in checkpoint["ema"].items()}
    assert all(p.shape == ema[n].shape and p.dtype == ema[n].dtype for n, p in parameters.items())
    assert clocks(module, optimizer) == {
        "tensors": 4,
        "states": 4,
        "steps": [float(checkpoint["updates"])],
    }
    assert inherited_hash(module) == checkpoint["inherited_hash"]
    torch.set_rng_state(checkpoint["CPU_RNG"])
    if checkpoint.get("CUDA_RNG") is not None:
        torch.cuda.set_rng_state(checkpoint["CUDA_RNG"])
    assert torch.equal(torch.get_rng_state(), checkpoint["CPU_RNG"])
    if checkpoint.get("CUDA_RNG") is not None:
        assert torch.equal(torch.cuda.get_rng_state(), checkpoint["CUDA_RNG"])
    return optimizer, ema
